mapper.select:
SELECT rc.* FROM rule_config rc
LEFT JOIN `ruoyi-vue-pro`.system_users su ON rc.auditor_id = su.id AND su.deleted = 0

    rc.deleted = 0

        AND rc.name LIKE CONCAT('%', #{reqVO.name}, '%')


        AND rc.type = #{reqVO.type}


        AND rc.status = #{reqVO.status}


        AND rc.scene = #{reqVO.scene}


        AND rc.auditor_id = #{reqVO.auditorId}


        AND rc.match_count = #{reqVO.matchCount}


        AND rc.description LIKE CONCAT('%', #{reqVO.description}, '%')


        AND rc.gift_ratio = #{reqVO.giftRatio}


        AND rc.audit_time BETWEEN
            DATE_FORMAT(FROM_UNIXTIME(#{reqVO.auditStartTime} / 1000), '%Y-%m-%d %H:%i:%s')
            AND DATE_FORMAT(FROM_UNIXTIME(#{reqVO.auditEndTime} / 1000), '%Y-%m-%d %H:%i:%s')


        AND rc.audit_time >= DATE_FORMAT(FROM_UNIXTIME(#{reqVO.auditStartTime} / 1000), '%Y-%m-%d %H:%i:%s')


        AND rc.audit_time <= DATE_FORMAT(FROM_UNIXTIME(#{reqVO.auditEndTime} / 1000), '%Y-%m-%d %H:%i:%s')


        AND rc.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}


        AND rc.effect_time BETWEEN #{reqVO.effectTime[0]} AND #{reqVO.effectTime[1]}


        AND su.nickname LIKE CONCAT('%', #{reqVO.auditorName}, '%')


ORDER BY rc.id DESC
